import unittest
from candidate import modp

class TestModp(unittest.TestCase):
    def test_modp_positive_numbers(self):
        self.assertEqual(modp(3, 5), 3)

    def test_modp_large_number(self):
        self.assertEqual(modp(1101, 101), 2)

    def test_modp_zero(self):
        self.assertEqual(modp(0, 101), 1)

    def test_modp_small_number(self):
        self.assertEqual(modp(3, 11), 8)

    def test_modp_large_large_number(self):
        self.assertEqual(modp(100, 101), 1)

    def test_modp_negative_numbers(self):
        self.assertRaises(TypeError, modp, -3, 5)

    def test_modp_non_positive_p(self):
        self.assertRaises(TypeError, modp, 3, -5)

    def test_modp_negative_numbers(self):
        self.assertRaises(TypeError, modp, -3, -5)

    def test_modp_non_integer(self):
        self.assertRaises(TypeError, modp, '3', 5)

    def test_modp_non_integer_p(self):
        self.assertRaises(TypeError, modp, 3, '5')
